using AirwaysMergeSafeServer.Models;

namespace AirwaysMergeSafeServer.Services;

/// <summary>
/// AirCarSpec — specification record for air vehicles (flying cars / eVTOLs).
/// Mirrors VehicleSpec but adds air-specific fields: Wingspan, MaxAltitude, CruiseSpeed.
/// Used by the 3D Air Scene for vehicle rendering and identification.
/// </summary>
public sealed record AirCarSpec(
    string   Type,
    string   Make,
    string   Model,
    string   Size,
    string   Icon,
    string   BrandLogo,
    string   SideViewLogo,
    string[] Colors,
    float    LengthM,
    float    WidthM,       // Wingspan
    float    HeightM,
    float    MaxAltitudeM,
    float    CruiseSpeedMph
);

/// <summary>
/// Interface for the AirCar Vehicle Registry — injected via DI as a singleton.
/// </summary>
public interface IAirCarRegistry
{
    IReadOnlyList<AirCarSpec> All { get; }
}

/// <summary>
/// AirCarRegistry — static registry of 12 air car (flying car / eVTOL) specifications.
